// Assembles the OpenAPI document from the Zod source (brief §5).
import { operations } from '../operations/index.ts';
import { documentBase, sharedComponents } from './base.ts';
import { emitSchema, emitTree } from './emit.ts';
import { namedSchemas } from './registry.ts';
import { toYaml } from './yaml.ts';

export const YAML_HEADER =
  '# GENERATED by `pnpm contract:build` from packages/contracts (Zod). Do not edit by hand.\n' +
  '# Change it through a PR labelled contract-change, approved by the other agent.';

export function buildDocument(): Record<string, unknown> {
  const paths: Record<string, Record<string, unknown>> = {};
  const seen = new Set<string>();
  for (const op of operations) {
    const key = `${op.method} ${op.path}`;
    if (seen.has(key)) throw new Error(`operation defined twice: ${key}`);
    seen.add(key);
    (paths[op.path] ??= {})[op.method] = emitTree(op.spec);
  }
  const ids = operations.map((o) => o.spec.operationId);
  const duplicate = ids.find((id, i) => ids.indexOf(id) !== i);
  if (duplicate) throw new Error(`operationId used twice: ${duplicate}`);

  return {
    ...documentBase,
    paths,
    components: {
      ...(emitTree(sharedComponents) as Record<string, unknown>),
      schemas: Object.fromEntries(
        namedSchemas().map(({ name, schema }) => [name, emitSchema(schema, true)]),
      ),
    },
  };
}

export function buildYaml(): string {
  return toYaml(buildDocument(), YAML_HEADER);
}
